<!doctype html><html><head><meta charset="utf-8"><title>Huddle</title><style>body{margin:0;font:15px Arial;display:flex;height:100vh}.sidebar{background:#3f0e40;color:white;width:240px;padding:20px}.main{flex:1;padding:25px}button{padding:9px;background:#007a5a;color:white;border:0;margin:3px}.channel-entry{display:block;color:white;padding:8px;cursor:pointer}</style></head><body><aside class="sidebar"><h2 id="workspace-header">Huddle</h2><div data-testid="channel-list" id="channel-list"></div><button data-testid="new-channel-btn">New channel</button></aside><main class="main"><form id="auth-form" data-mode="signup"><input name="username" placeholder="username"><input name="password" type="password" placeholder="password"><button id="auth-submit" data-testid="auth-submit">Sign up</button><button type="button" id="auth-toggle" data-testid="auth-toggle">Login</button><div id="auth-error"></div></form><h2 id="channel-title"></h2><div id="channel-topic"></div><div id="message-list"></div><input id="message-input"><button id="send-btn" data-testid="send-btn">Send</button><span id="current-user"></span><button id="logout-btn">Logout</button></main><script src="/app.js"></script></body></html>
